"""Generate docs/opponent-model.md from the live code: trait definitions, archetype priors, and measured behavior.

  python3 tools/make_opponent_doc.py
The tables come straight from TRAIT_DOC, TRAIT_RANGE, ARCH_PRIOR, ARCH, and a decision-level measurement, so they cannot drift from the code.
"""
import os, sys, math
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, '..', 'tests'))
from harness import engine
import test_opponents as T
e = engine()
doc = e.run('return {doc:TRAIT_DOC,range:TRAIT_RANGE,prior:ARCH_PRIOR,arch:Object.keys(ARCH).map(function(k){return [k,ARCH[k].n,ARCH[k].skill,ARCH[k].st,ARCH[k].tip];}),stats:ARCH_STATS};')
P = T.probe(); rt = T.rt
L = ['# Opponent model', '', 'Generated by `tools/make_opponent_doc.py` from the running code. Narrative and limitations are in `docs/stage-03-report.md`.', '',
     '## How individuals are built', '',
     'An archetype supplies the mean of each trait. Four latent factors are drawn per player (zL looseness, zA aggression, zS stickiness, zK skill) and load onto the traits, so related traits move together. `spread` scales how far one player strays from the archetype. Traits are clamped to the ranges below, and contradictory combinations are repaired (a passive player cannot bluff a lot, a very tight player does not chase draws, a sticky player does not overfold, a very aggressive player does check-raise, the river barrel never exceeds the turn barrel).', '',
     '## Traits', '', '| Trait | Meaning | Range | How it is drawn |', '| --- | --- | --- | --- |']
for k, meaning, how in doc['doc']:
    r = doc['range'].get(k); L.append('| `%s` | %s | %s | %s |' % (k, meaning, ('%s to %s' % tuple(r)) if r else 'style', how))
L += ['', '## Archetypes', '', '| Type | Skill | Spread | Turn / river barrel | Pair bias | Call cap | Check-raise | Size noise | Adapt | Attention |', '| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |']
for k, n, sk, st, tip in doc['arch']:
    pr = doc['prior'].get(k)
    if pr: L.append('| %s (`%s`) | %s | %.1f | %.2f / %.2f | %+.2f | %.1f | %.1f | %.2f | %.2f | %.2f |' % (n, k, sk, pr['spread'], pr['barrel'][0], pr['barrel'][1], pr['pairBias'], pr['cap'], pr['xr'], pr['sizeNoise'], pr['adapt'], pr['attn']))
L += ['', '## Behavior by type (decision level)', '', 'Over %d decisions per type (150 fresh individuals each, a fixed bank of random hands on random boards). "Weak pair" is a weak or middle pair; "bet" is how often the player bets when checked to; "river bluff" is a bet with nothing on the river; "20x" is a call of a 20x-pot bet with a random river hand.' % P['station']['n'], '',
      '| Type | Calls weak pair vs 2/3 pot | Folds flop / turn / river to 2/3 pot | Bets when checked to | River bluff | Raises vs 2/3 pot | Calls 20x pot |', '| --- | --- | --- | --- | --- | --- | --- |']
for k in T.TYPES:
    f = P[k]; L.append('| %s | %.0f%% | %.0f%% / %.0f%% / %.0f%% | %.0f%% | %.1f%% | %.0f%% | %.0f%% |' % (k, 100 * rt(f['callWeak']), 100 * rt(f['foldBet']['1']), 100 * rt(f['foldBet']['2']), 100 * rt(f['foldBet']['3']), 100 * rt(f['bet']), 100 * rt(f['bluffRiver']), 100 * rt(f['raise']), 100 * rt(f['callBig']['20'])))
L += ['', '## What a hero can observe (`ARCH_STATS`, measured with `tools/measure_archetypes.py`)', '', '| Type | Plays (VPIP) | Raises pre-flop (PFR) | Bet share after the flop | Folds to a bet |', '| --- | --- | --- | --- | --- |']
for k in T.TYPES:
    s = doc['stats'][k]; L.append('| %s | %.0f%% | %.0f%% | %.0f%% | %.0f%% |' % (k, 100 * s[0], 100 * s[1], 100 * s[2], 100 * s[4]))
L += ['', '## Limited observation of the hero', '', 'Each opponent keeps Beta counts of what it saw the hero do (pre-flop play, pre-flop raises, post-flop aggression, folds to bets, hands shown at showdown). An event is noticed with probability `attn` (30% of that if the player already folded). Belief = (k x prior + successes) / (k + trials), with population priors `POP` in `index.html`; trials are capped so old evidence fades. How much a belief changes play = `adapt` x trials / (trials + 20). Nothing is learned from events the player did not see.', '']
open(os.path.join(HERE, '..', 'docs', 'opponent-model.md'), 'w', encoding='utf-8').write('\n'.join(L)); print('wrote docs/opponent-model.md', len(L), 'lines')
